// ButtonContent — Adw.ButtonContent
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles buttoncontent with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ButtonContentProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.ButtonContent */
  canShrink?: boolean

  /** utf8, from Adw.ButtonContent */
  iconName?: string

  /** utf8, from Adw.ButtonContent */
  label?: string

  /** gboolean, from Adw.ButtonContent */
  useUnderline?: boolean
}

export function ButtonContent({ className, children, label }: ButtonContentProps) {
  return (
    <div className={cn(className)}>
      {label}
      {children}
    </div>
  )
}
